//! Optional runtimes receive immutable inputs and a separate filesystem socket.
use crate::{macos_snapshot::Image,macos_supervisor::{Host,Limits,Output},macos_seatbelt::Role,macos_filesystem_session::{Grant,guest_name},unix_filesystem::Broker};
use sha2::{Digest,Sha256};use std::{io,os::fd::AsRawFd,path::{Path,PathBuf},sync::{Arc,atomic::{AtomicBool,AtomicUsize,Ordering}},time::Duration};
pub fn run(host:&Host,runtime:&[u8],expected:&str,engine:&str,adapter:Option<(&[u8],&str)>,program:&[u8],args:&[String],grants:&[Grant],base:&Path,limits:Limits,private:&[PathBuf])->io::Result<Output>{
 let role=match(engine,adapter.is_some()){("javascript",true)=>Role::JavaScript,("wasm",false)=>Role::Wasm,_=>return Err(io::Error::other("explicit optional engine inputs required"))};
 let mut image=Image::runtime(runtime,expected,base)?;let digest=format!("sha256:{:x}",Sha256::digest(program));
 let mut arguments=if let Some((adapter,hash))=adapter{let control=image.runtime_input("control.mjs",adapter,hash)?;let program=image.runtime_input("program.mjs",program,&digest)?;
  vec!["--jitless".into(),"--max-old-space-size=256".into(),"--input-type=module".into(),"--eval".into(),"import fs from 'node:fs';const control=process.argv[1],program=process.argv[2];process.argv=[process.argv[0],program,...process.argv.slice(3)];await import('data:text/javascript;base64,'+fs.readFileSync(control).toString('base64'));await import('data:text/javascript;base64,'+fs.readFileSync(program).toString('base64'));".into(),control.to_str().ok_or_else(||io::Error::other("Unicode control required"))?.into(),program.to_str().ok_or_else(||io::Error::other("Unicode module required"))?.into()]
 }else{let module=image.runtime_input("program.wasm",program,&digest)?;vec![module.to_str().ok_or_else(||io::Error::other("Unicode module required"))?.into(),digest,"--".into()]};arguments.extend_from_slice(args);
 if grants.len()>128{return Err(io::Error::other("engine filesystem root budget"));}let mut broker=Broker::default();let mut roots=vec![];let(mut read,mut write)=(vec![],vec![]);let mut seen=std::collections::HashSet::new();
 for grant in grants{guest_name(&grant.guest)?;if !seen.insert(&grant.guest){return Err(io::Error::other("duplicate engine filesystem mapping"));}for protected in private.iter().map(PathBuf::as_path).chain([host.directory(),image.directory()]){if grant.path.starts_with(protected)||protected.starts_with(&grant.path){return Err(io::ErrorKind::PermissionDenied.into());}}let token=broker.add_root(&grant.path,grant.read,grant.write)?;roots.push(serde_json::json!({"guest":grant.guest,"handle":token.to_string(),"read":grant.read,"write":grant.write}));if grant.read{read.push(&grant.guest);}if grant.write{write.push(&grant.guest);}}
 let environment=[("KELFT_ENGINE_PROFILE".into(),format!("{engine}-kfs/1")),("KELFT_FS_ROOTS".into(),serde_json::to_string(&roots)?),("KELFT_FS_CWD".into(),"/project".into()),("KELFT_FS_REQUEST".into(),"3".into()),("KELFT_FS_RESPONSE".into(),"3".into()),("KELFT_CAPABILITIES".into(),serde_json::json!({"execute":false,"read":read,"write":write}).to_string())];
 // The supervisor owns the deadline and shuts this socket down on every exit.
 // An idle-read timer starts before worker setup and would race that deadline.
 let(mut server,client)=std::os::unix::net::UnixStream::pair()?;server.set_write_timeout(Some(Duration::from_millis(limits.wall_ms.max(1))))?;let cleanup=server.try_clone()?;let cancel=Arc::new(AtomicBool::new(false));let total=Arc::new(AtomicUsize::new(0));let failed=cancel.clone();let count=total.clone();
 let service=std::thread::Builder::new().name("kelft-engine-filesystem".into()).spawn(move||{let mut output=server.try_clone()?;crate::engine_channel::serve(&mut server,&mut output,limits.output_bytes,count,failed,|request|broker.execute(request))})?;
 let result=host.run_metered(&image,role,&arguments,&environment,&[(client.as_raw_fd(),3)],None,limits,Some(&cancel),total);drop(client);let shutdown=cleanup.shutdown(std::net::Shutdown::Both);let captured=service.join().map_err(|_|io::Error::other("engine filesystem service panicked"))?;
 if let Err(error)=shutdown{if error.raw_os_error()!=Some(libc::ENOTCONN){return Err(error);}}
 let mut output=result?;match captured{Ok(stderr)=>output.stderr.extend(stderr),Err(error)=>if output.failure.is_none(){output.failure=Some(format!("optional engine channel failed: {error}"));output.exit=None;}}if cancel.load(Ordering::Acquire)&&output.failure.is_none(){output.failure=Some("optional engine channel failed".into());output.exit=None;}image.verify()?;Ok(output)
}
